package hu.keepimproving.android;

import android.app.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.function.*;

/** Scrollable native forms. Drafts survive leaving the app and rotation. */
final class PhoneEditor {
    final MainActivity a; final String kind,key; final JSONObject value; final LinearLayout box; final AlertDialog dialog;
    Consumer<JSONObject> customSave;Runnable customVisibility;
    final Map<String,List<View>> fields=new HashMap<>();
    PhoneEditor(MainActivity a,String kind,JSONObject original,String title){
        this.a=a;this.kind=kind;boolean exists=false;if(a.state!=null){if(kind.equals("budget"))for(var b:a.state.budgets())if(b.rule().optString("id").equals(original.optString("id")))exists=true;if(kind.equals("reminder"))for(int i=0;i<a.state.reminders().length();i++)if(a.state.reminders().optJSONObject(i).optString("id").equals(original.optString("id")))exists=true;}
        key=kind+":"+(kind.startsWith("remote:")?original.optString("id","config"):kind.equals("focus")?"config":kind.equals("step")?original.optString("id"):exists?original.optString("id"):"new");
        String saved=a.getSharedPreferences("drafts",0).getString(key,"");value=saved.isEmpty()?PhoneRules.copy(original):PhoneRules.object(saved);
        box=a.column();box.setPadding(a.dp(20),a.dp(8),a.dp(20),a.dp(16));ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);scroll.addView(box);
        dialog=new AlertDialog.Builder(a).setTitle(title).setView(scroll).setNegativeButton(a.t("Later","Később"),null).setNeutralButton(a.t("Discard draft","Vázlat elvetése"),null).setPositiveButton(R.string.save,null).create();
        dialog.setOnShowListener(d->{
            dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->new AlertDialog.Builder(a).setTitle(a.t("Discard these edits?","Elveted a módosításokat?")).setNegativeButton(R.string.cancel,null).setPositiveButton(a.t("Discard","Elvetés"),(x,w)->{clear();dialog.dismiss();}).show());
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->save());
        });
        if(!saved.isEmpty())box.addView(a.text(a.t("Your unfinished edits were restored.","Visszaállítottuk a félbehagyott módosításokat."),13,MainActivity.ACCENT));
    }
    void draft(){a.getSharedPreferences("drafts",0).edit().putString(key,value.toString()).apply();}
    void clear(){a.getSharedPreferences("drafts",0).edit().remove(key).apply();}
    void set(String field,Object data){PhoneRules.set(value,field,data);draft();visibility();}
    void tracked(String field,int start){List<View> list=new ArrayList<>();for(int i=start;i<box.getChildCount();i++)list.add(box.getChildAt(i));fields.put(field,list);visibility();}
    void show(String field,boolean visible){for(View v:fields.getOrDefault(field,List.of()))v.setVisibility(visible?View.VISIBLE:View.GONE);}
    void visibility(){
        if(customVisibility!=null)customVisibility.run();
        if(kind.equals("budget")){show("minutes",value.optBoolean("limit"));show("block",value.optBoolean("limit"));}
        if(kind.equals("step")){show("clock",value.optString("mode").equals("clock"));show("minutes",!Set.of("clock","sessions").contains(value.optString("mode")));show("sessions",value.optString("mode").equals("sessions"));show("session_hint",value.optString("mode").equals("sessions"));show("duration",value.optString("kind").equals("break"));show("sound",!value.optString("kind").equals("block"));}
        if(kind.equals("reminder")){show("clock",value.optString("trigger").equals("clock"));show("rounds",value.optString("trigger").equals("rounds"));show("package",value.optString("action").equals("app"));for(String field:new String[]{"work","short","long","cycles","focus_heading"})show(field,value.optString("action").equals("focus"));}
    }
    void hint(String en,String hu){box.addView(a.text(a.t(en,hu),13,MainActivity.MUTED));}
    void text(String field,String label,int max,boolean multiline){
        box.addView(a.text(label,14,MainActivity.TEXT));EditText input=new EditText(a);input.setText(value.optString(field));input.setSingleLine(!multiline);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});if(multiline){input.setMinLines(2);input.setMaxLines(4);}box.addView(input);
        input.addTextChangedListener(watcher(s->set(field,s)));
    }
    static TextWatcher watcher(Consumer<String> change){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){change.accept(s.toString());}public void afterTextChanged(Editable e){}};}
    void number(String field,String label,int min,int max){
        int start=box.getChildCount();
        box.addView(a.text(label+" ("+min+"–"+max+")",14,MainActivity.TEXT));EditText input=new EditText(a);input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|(min<0?android.text.InputType.TYPE_NUMBER_FLAG_SIGNED:0));input.setText(Integer.toString(value.optInt(field)));input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(7)});box.addView(input);
        input.addTextChangedListener(watcher(s->{try{int n=Integer.parseInt(s);set(field,n);input.setError(n<min||n>max?a.t("Outside the allowed range","Az engedélyezett tartományon kívül"):null);}catch(NumberFormatException e){set(field,-999999);input.setError(a.t("Enter a number","Adj meg egy számot"));}}));tracked(field,start);
    }
    void toggle(String field,String label){int start=box.getChildCount();Switch s=new Switch(a);s.setText(label);s.setTextColor(MainActivity.TEXT);s.setMinHeight(a.dp(48));s.setChecked(value.optBoolean(field));s.setOnCheckedChangeListener((b,on)->ScrollPosition.change(s,()->set(field,on)));box.addView(s);tracked(field,start);}
    void select(String field,String label,String[] keys,String[] labels){box.addView(a.text(label,14,MainActivity.TEXT));int current=Arrays.asList(keys).indexOf(value.optString(field));box.addView(a.spinner(labels,Math.max(0,current),i->set(field,keys[i])));}
    void clock(String field,String label){int start=box.getChildCount();Button b=a.button("",()->{});Runnable refresh=()->b.setText(label+"  "+String.format(Locale.ROOT,"%02d:%02d",value.optInt(field)/60,value.optInt(field)%60));refresh.run();b.setOnClickListener(v->new TimePickerDialog(a,(picker,h,m)->{set(field,h*60+m);refresh.run();},value.optInt(field)/60,value.optInt(field)%60,true).show());box.addView(b);tracked(field,start);}
    void weekdays(){a.heading(box,a.t("Active days","Aktív napok"));String[] labels=a.t("Mon,Tue,Wed,Thu,Fri,Sat,Sun","H,K,Sze,Cs,P,Szo,V").split(",");LinearLayout row=new LinearLayout(a);
        for(int i=0;i<7;i++){final int bit=1<<i;CheckBox day=new CheckBox(a);day.setText(labels[i]);day.setTextSize(11);day.setButtonDrawable((android.graphics.drawable.Drawable)null);day.setGravity(Gravity.CENTER);day.setMinHeight(a.dp(48));day.setPadding(0,0,0,0);day.setChecked((value.optInt("days")&bit)!=0);day.setTextColor(day.isChecked()?MainActivity.ACCENT:MainActivity.MUTED);day.setBackground(a.background(MainActivity.CARD));day.setOnCheckedChangeListener((b,on)->{set("days",on?value.optInt("days")|bit:value.optInt("days")&~bit);day.setTextColor(on?MainActivity.ACCENT:MainActivity.MUTED);});row.addView(day,new LinearLayout.LayoutParams(0,-2,1));}box.addView(row);
    }
    void apps(String field,String label){Button b=a.button("",()->{});Runnable refresh=()->b.setText(label+" ("+PhoneRules.array(value.optString(field,"[]")).length()+")");refresh.run();b.setOnClickListener(v->chooseApps(a,PhoneRules.array(value.optString(field,"[]")),selected->{set(field,selected);refresh.run();},false));box.addView(b);}
    static void chooseApps(MainActivity a,JSONArray original,Consumer<JSONArray> save,boolean single){
        LinkedHashSet<String> selected=new LinkedHashSet<>();for(int i=0;i<original.length();i++)selected.add(original.optString(i));LinearLayout layout=a.column();layout.setPadding(a.dp(16),0,a.dp(16),0);EditText search=new EditText(a);search.setHint(a.t("Search applications","Alkalmazás keresése"));search.setSingleLine(true);layout.addView(search);ScrollView scroll=new ScrollView(a);LinearLayout rows=a.column();scroll.addView(rows);layout.addView(scroll,new LinearLayout.LayoutParams(-1,a.dp(300)));
        Runnable render=()->{rows.removeAllViews();String query=search.getText().toString().toLowerCase(Locale.ROOT);int count=0;for(var app:a.apps){if(!app.name().toLowerCase(Locale.ROOT).contains(query)&&!app.pkg().contains(query))continue;CheckBox check=new CheckBox(a);check.setText(app.name());check.setTextColor(MainActivity.TEXT);check.setMinHeight(a.dp(48));check.setChecked(selected.contains(app.pkg()));check.setOnCheckedChangeListener((b,on)->{if(on){if(single){selected.clear();for(int j=0;j<rows.getChildCount();j++)if(rows.getChildAt(j)!=b&&rows.getChildAt(j) instanceof CheckBox other)other.setChecked(false);}selected.add(app.pkg());}else selected.remove(app.pkg());});rows.addView(check);count++;}if(count==0)rows.addView(a.text(a.t("No matching applications","Nincs találat"),14,MainActivity.MUTED));};
        search.addTextChangedListener(watcher(s->render.run()));render.run();new AlertDialog.Builder(a).setTitle(a.t("Select applications","Alkalmazások kiválasztása")).setView(layout).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.save,(d,w)->save.accept(new JSONArray(selected))).show();
    }
    void devices(boolean budget,String owner){PhoneScopeEditor.add(this,budget,owner);}
    String localDevice(){try(PhoneStore s=new PhoneStore(a)){return s.device();}}
    static void budget(MainActivity a,JSONObject original){
        PhoneEditor e=new PhoneEditor(a,"budget",original,a.t("Budget","Keret"));e.text("name",a.t("Name","Név"),100,false);e.toggle("enabled",a.t("Enabled","Bekapcsolva"));e.weekdays();
        e.devices(true,e.localDevice());
        e.select("category",a.t("Include category","Kategória hozzáadása"),new String[]{"","games","apps","all"},new String[]{a.t("Selected applications only","Csak a kijelölt alkalmazások"),a.getString(R.string.games),a.getString(R.string.apps),a.t("All applications","Minden alkalmazás")});e.apps("apps",a.t("Select applications","Alkalmazások kiválasztása"));

        e.toggle("limit",a.t("Daily time limit","Napi időkorlát"));e.number("minutes",a.t("Daily allowance (minutes)","Napi keret (perc)"),0,1440);e.toggle("block",a.t("Cover apps when time runs out","Alkalmazások eltakarása lejáratkor"));e.number("allowance",a.t("One-time daily extension (minutes)","Naponta egyszer kérhető hosszabbítás (perc)"),0,60);
        e.hint("A zero-minute budget blocks immediately. Covering apps requires the separate protection permission.","A nulla perces keret azonnal tilt. Az eltakarás külön védelmi engedélyt igényel.");
        a.heading(e.box,a.t("Warnings and restrictions","Figyelmeztetések és korlátozások"));LinearLayout steps=a.column();e.box.addView(steps);Runnable[] render={null};render[0]=()->{steps.removeAllViews();JSONArray items=e.value.optJSONArray("steps");if(items==null)return;for(int i=0;i<items.length();i++){int index=i;JSONObject step=items.optJSONObject(i);if(step==null)continue;String kind=switch(step.optString("kind")){case "break"->a.t("Break","Szünet");case "block"->a.t("Cover apps","Eltakarás");default->a.t("Notification","Értesítés");};String when=step.optString("mode").equals("clock")?String.format(Locale.ROOT,"%02d:%02d",step.optInt("clock")/60,step.optInt("clock")%60):step.optString("mode").equals("sessions")?step.optInt("sessions",5)+a.t(" sessions"," munkamenet"):step.optInt("minutes")+a.t(" min"," perc");steps.addView(a.button(kind+" · "+when,()->step(e,index,render[0])));}steps.addView(a.button(a.t("+ Add action","+ Művelet hozzáadása"),()->step(e,-1,render[0])));};render[0].run();e.dialog.show();
    }
    static void step(PhoneEditor parent,int index,Runnable refresh){
        MainActivity a=parent.a;JSONArray list=parent.value.optJSONArray("steps");JSONObject s=index<0?PhoneRules.step():PhoneRules.copy(list.optJSONObject(index));PhoneEditor e=new PhoneEditor(a,"step",s,a.t("Action","Művelet"));
        e.select("kind",a.t("Action","Művelet"),new String[]{"notify","break","block"},new String[]{a.t("Notify","Értesítés"),a.t("Repeated break","Ismétlődő szünet"),a.t("Cover until daily reset","Eltakarás a napi megújulásig")});
        e.select("mode",a.t("When","Mikor"),new String[]{"usage","clock","relative","sessions"},new String[]{a.t("Used time","Felhasznált idő után"),a.t("Time of day","Adott időpontban"),a.t("Relative to the limit","Lejárathoz képest"),a.t("Daily session limit","Napi munkamenetkorlát")});e.number("minutes",a.t("Minutes (relative: negative = before expiry)","Perc (lejárathoz képest: negatív = előtte)"),-10080,10080);if(!e.value.has("sessions"))PhoneRules.set(e.value,"sessions",5);e.number("sessions",a.t("Allowed sessions","Engedélyezett munkamenetek"),1,10000);int hintStart=e.box.getChildCount();e.hint("The action starts on the next session after the allowed count. The count resets at the budget renewal. After a break, the same number of new sessions is allowed.","A művelet az engedélyezett darabszámot követő munkamenetnél indul. A számláló a keret napi megújulásakor nullázódik. Szünet után ugyanennyi új munkamenet engedélyezett.");e.tracked("session_hint",hintStart);e.clock("clock",a.t("Time of day","Időpont"));e.number("duration",a.t("Break duration (minutes)","Szünet hossza (perc)"),1,180);e.toggle("sound",a.t("Sound","Hang"));
        e.hint("A usage break repeats after each selected amount of active time. Relative timing requires a daily limit and cannot be used for breaks.","A használati szünet a megadott aktív időnként ismétlődik. Lejárathoz viszonyított időzítéshez napi keret szükséges, és szünetnél nem használható.");
        e.dialog.setOnShowListener(d->{e.dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{JSONArray next=PhoneRules.array(list.toString());try{if(index<0)next.put(e.value);else next.put(index,e.value);JSONObject test=PhoneRules.copy(parent.value);PhoneRules.set(test,"steps",next);if(test.optString("name").isBlank())PhoneRules.set(test,"name","Draft");if(test.optString("category").isEmpty()&&test.optJSONArray("apps").length()==0)PhoneRules.set(test,"category","all");PhoneRules.validate(test,false);parent.set("steps",next);e.clear();e.dialog.dismiss();refresh.run();}catch(Exception ex){Toast.makeText(a,a.t("Check the timing and values. Maximum 20 steps.","Ellenőrizd az időzítést és az értékeket. Legfeljebb 20 lépés."),Toast.LENGTH_LONG).show();}});e.dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setText(a.t("Remove step","Lépés törlése"));e.dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{if(index>=0){JSONArray next=PhoneRules.array(list.toString());next.remove(index);parent.set("steps",next);}e.clear();e.dialog.dismiss();refresh.run();});});e.dialog.show();
    }
    static void reminder(MainActivity a,JSONObject original){
        PhoneEditor e=new PhoneEditor(a,"reminder",original,a.t("Reminder","Emlékeztető"));e.text("title",a.t("Title","Cím"),80,false);e.text("text",a.t("Message","Üzenet"),1000,true);e.toggle("enabled",a.t("Enabled","Bekapcsolva"));e.weekdays();
        e.devices(false,e.localDevice());
        String[] triggers=e.value.optString("_shared").isEmpty()?new String[]{"clock","rounds","startup"}:new String[]{"clock","rounds","startup","warning","limit","session","bedtime"};e.select("trigger",a.t("When","Mikor"),triggers,Arrays.stream(triggers).map(k->switch(k){case "clock"->a.t("Time of day","Adott időpontban");case "rounds"->a.t("Daily focus goal","Napi fókuszcél elérésekor");case "startup"->a.t("When opening the app","Az alkalmazás megnyitásakor");default->RemoteLabels.label(a,k);}).toArray(String[]::new));e.clock("clock",a.t("Time","Időpont"));e.number("rounds",a.t("Completed focus rounds","Befejezett fókuszkörök"),1,100);e.toggle("sound",a.t("Sound","Hang"));e.number("timeout",a.t("Dismiss after seconds (0 = keep)","Eltűnés ennyi másodperc után (0 = marad)"),0,3600);
        e.select("action",a.t("Notification action","Értesítés művelete"),new String[]{"none","focus","app"},new String[]{a.t("Open Keep Improving","Keep Improving megnyitása"),a.t("Start Pomodoro","Pomodoro indítása"),a.t("Open an application","Alkalmazás megnyitása")});
        Button choose=a.button("",()->{});Runnable selectedLabel=()->{String pkg=e.value.optString("package"),name=pkg;for(var app:a.apps)if(app.pkg().equals(pkg))name=app.name();choose.setText(a.t("Target application: ","Célalkalmazás: ")+(name.isEmpty()?a.t("Choose","Kiválasztás"):name));};selectedLabel.run();choose.setOnClickListener(v->chooseApps(a,new JSONArray().put(e.value.optString("package")),selected->{e.set("package",selected.optString(0,""));selectedLabel.run();},true));e.box.addView(choose);e.tracked("package",e.box.getChildCount()-1);
        a.heading(e.box,a.t("Pomodoro action settings","Pomodoro művelet beállításai"));e.tracked("focus_heading",e.box.getChildCount()-1);e.focusNumbers();e.hint("Each reminder appears once a day.","Az emlékeztető naponta egyszer jelenik meg.");e.dialog.show();
    }
    void focusNumbers(){number("work",a.t("Focus (minutes)","Fókusz (perc)"),1,240);number("short",a.t("Short break (minutes)","Rövid szünet (perc)"),0,60);number("long",a.t("Long break (minutes)","Hosszú szünet (perc)"),0,180);number("cycles",a.t("Rounds before long break (0 = single timer)","Körök hosszú szünetig (0 = egyszeri időzítő)"),0,12);}
    static void focus(MainActivity a){if(a.state==null)return;PhoneEditor e=new PhoneEditor(a,"focus",a.state.config(),a.t("Focus settings","Fókusz beállításai"));e.focusNumbers();e.apps("apps",a.t("Cover these apps during focus","Fókusz közben eltakart alkalmazások"));
        a.heading(e.box,a.t("Include budget groups","Keretcsoportok bevonása"));LinkedHashSet<String> groups=new LinkedHashSet<>();JSONArray chosen=e.value.optJSONArray("groups");if(chosen!=null)for(int i=0;i<chosen.length();i++)groups.add(chosen.optString(i));for(var view:a.state.budgets()){String id=view.rule().optString("id");CheckBox check=new CheckBox(a);check.setText(view.rule().optString("name"));check.setChecked(groups.contains(id));check.setMinHeight(a.dp(48));check.setOnCheckedChangeListener((b,on)->{if(on)groups.add(id);else groups.remove(id);e.set("groups",new JSONArray(groups));});e.box.addView(check);}e.hint("Stop the timer before changing durations. Breaks start automatically; you start each focus round.","Az időtartamok módosításához állítsd le az időzítőt. A szünet automatikus, a fókuszkört te indítod.");e.dialog.show();}
    void save(){
        if(customSave!=null){try{customSave.accept(PhoneRules.copy(value));}catch(RuntimeException e){Toast.makeText(a,a.t("Check the entered values.","Ellenőrizd a megadott értékeket."),Toast.LENGTH_LONG).show();}return;}
        try{if(kind.equals("focus"))PhoneFocus.validate(value);else PhoneRules.validate(value,kind.equals("reminder"));if(kind.equals("reminder")&&value.optString("action").equals("app")&&value.optString("package").isEmpty())throw new IllegalArgumentException();}
        catch(Exception e){Toast.makeText(a,a.t("Check the name, selected apps and numeric ranges.","Ellenőrizd a nevet, a kijelölt alkalmazásokat és az értékhatárokat."),Toast.LENGTH_LONG).show();return;}
        dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);JSONObject saved=PhoneRules.copy(value);
        CollectionJob.WORK.execute(()->{try{PhoneRuntime.State state=PhoneRuntime.refresh(a,false);try(PhoneStore store=new PhoneStore(a)){
            if(kind.equals("focus")){if(state.focus().optBoolean("running"))throw new IllegalStateException("running");var db=store.getWritableDatabase();db.beginTransaction();try{store.put("focus_config",saved.toString());store.put("focus_timer",PhoneFocus.state(saved).toString());db.setTransactionSuccessful();}finally{db.endTransaction();}}
            else store.saveRule(kind,saved);
        }PhoneRuntime.refresh(a,false);PhoneRuntime.changed(a);a.runOnUiThread(()->{clear();dialog.dismiss();a.syncChanged();});}
        catch(Exception ex){a.runOnUiThread(()->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);Toast.makeText(a,"conflict".equals(ex.getMessage())?a.t("This rule changed on another device. Your draft is kept; sync and reopen the editor.","Ez a szabály egy másik eszközön megváltozott. A vázlat megmaradt; szinkronizálj, majd nyisd újra a szerkesztőt."):ex instanceof IllegalStateException?a.t("Stop the running timer first.","Előbb állítsd le a futó időzítőt."):a.t("Could not save changes.","Nem sikerült menteni."),Toast.LENGTH_LONG).show();});}});
    }
}
